Class Stopwatch
  Define total As Integer;

  Method Constructor()
    This.total <- 0;
  EndMethod

  Method Advance(seconds As Integer)
    This.total <- This.total + seconds;
  EndMethod

  Method Reading() As String
    Define hours As Integer <- This.total Div 3600;
    Define minutes As Integer <- This.total Mod 3600 Div 60;
    Return toText(hours) + " h " + toText(minutes) + " min " + toText(This.total Mod 60) + " s";
  EndMethod
EndClass

Algorithm Race
  Define watch As Stopwatch <- New Stopwatch();
  Define seconds As Integer;
  Read seconds;
  watch.Advance(seconds);
  Read seconds;
  watch.Advance(seconds);
  Write watch.Reading();
EndAlgorithm
